-- EchoTrails core schema foundation.
-- Public IDs are UUIDs generated by application code; runtime code should use UUIDv7.

CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE users (
    id uuid PRIMARY KEY,
    email text UNIQUE,
    role text NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'moderator', 'admin', 'service')),
    status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'restricted', 'suspended', 'banned', 'deleted')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz
);

CREATE TABLE user_profiles (
    user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    handle citext NOT NULL UNIQUE,
    display_name text,
    avatar_media_asset_id uuid,
    bio text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (handle ~ '^[a-zA-Z0-9_]{3,32}$'),
    CHECK (char_length(coalesce(display_name, '')) <= 80),
    CHECK (char_length(coalesce(bio, '')) <= 280)
);

CREATE TABLE auth_identities (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    provider text NOT NULL CHECK (provider IN ('apple', 'email')),
    provider_subject text NOT NULL,
    email text,
    verified_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (provider, provider_subject)
);

CREATE INDEX auth_identities_user_id_idx ON auth_identities(user_id);

CREATE TABLE sessions (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash bytea NOT NULL UNIQUE,
    user_agent text,
    ip_hash bytea,
    created_at timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz,
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz
);

CREATE INDEX sessions_user_id_idx ON sessions(user_id);
CREATE INDEX sessions_expires_at_idx ON sessions(expires_at);

CREATE TABLE devices (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    platform text NOT NULL CHECK (platform IN ('ios', 'web')),
    push_token_hash bytea UNIQUE,
    app_version text,
    locale text,
    timezone text,
    created_at timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz,
    disabled_at timestamptz
);

CREATE INDEX devices_user_id_idx ON devices(user_id);

CREATE TABLE consents (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    consent_type text NOT NULL CHECK (consent_type IN ('terms', 'privacy', 'age_gate', 'location', 'marketing')),
    version text NOT NULL,
    granted boolean NOT NULL,
    recorded_at timestamptz NOT NULL DEFAULT now(),
    source text NOT NULL DEFAULT 'app'
);

CREATE INDEX consents_user_id_idx ON consents(user_id);
CREATE UNIQUE INDEX consents_latest_unique_idx ON consents(user_id, consent_type, version);

CREATE TABLE places (
    id uuid PRIMARY KEY,
    name text NOT NULL,
    normalized_name text NOT NULL,
    description text,
    status text NOT NULL DEFAULT 'pending_review' CHECK (status IN ('active', 'pending_review', 'merged', 'restricted', 'removed', 'rejected')),
    location geography(Point, 4326) NOT NULL,
    boundary geography(Polygon, 4326),
    default_radius_meters integer NOT NULL DEFAULT 100 CHECK (default_radius_meters > 0),
    category text,
    sensitive boolean NOT NULL DEFAULT false,
    merged_into_place_id uuid REFERENCES places(id),
    created_by_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    CHECK (char_length(name) BETWEEN 1 AND 160)
);

CREATE INDEX places_location_gist_idx ON places USING gist(location);
CREATE INDEX places_boundary_gist_idx ON places USING gist(boundary);
CREATE INDEX places_status_idx ON places(status);
CREATE INDEX places_normalized_name_idx ON places(normalized_name);

CREATE TABLE place_provider_mappings (
    id uuid PRIMARY KEY,
    place_id uuid NOT NULL REFERENCES places(id) ON DELETE CASCADE,
    provider text NOT NULL,
    provider_place_id text NOT NULL,
    provider_payload jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (provider, provider_place_id)
);

CREATE INDEX place_provider_mappings_place_id_idx ON place_provider_mappings(place_id);

CREATE TABLE place_aliases (
    id uuid PRIMARY KEY,
    place_id uuid NOT NULL REFERENCES places(id) ON DELETE CASCADE,
    alias text NOT NULL,
    normalized_alias text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (place_id, normalized_alias)
);

CREATE INDEX place_aliases_normalized_alias_idx ON place_aliases(normalized_alias);

CREATE TABLE place_subscriptions (
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    place_id uuid NOT NULL REFERENCES places(id) ON DELETE CASCADE,
    notifications_enabled boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, place_id)
);

CREATE INDEX place_subscriptions_place_id_idx ON place_subscriptions(place_id);

CREATE TABLE echoes (
    id uuid PRIMARY KEY,
    author_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    place_id uuid NOT NULL REFERENCES places(id) ON DELETE RESTRICT,
    title text NOT NULL,
    content_mode text NOT NULL CHECK (content_mode IN ('text', 'audio', 'photo_set', 'video')),
    body_text text,
    caption_text text,
    status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'uploading', 'processing', 'pending_review', 'published', 'limited', 'removed', 'deleted', 'failed')),
    public_location geography(Point, 4326),
    private_creation_location geography(Point, 4326),
    location_proof_captured_at timestamptz,
    location_accuracy_meters numeric(8,2),
    creation_token_id uuid,
    sensitive_label text CHECK (sensitive_label IN ('none', 'user_labeled', 'moderator_labeled')),
    created_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    updated_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    CHECK (char_length(title) BETWEEN 1 AND 80),
    CHECK (body_text IS NULL OR char_length(body_text) <= 500),
    CHECK (caption_text IS NULL OR char_length(caption_text) <= 500),
    CHECK ((content_mode = 'text' AND body_text IS NOT NULL) OR (content_mode <> 'text'))
);

CREATE INDEX echoes_author_user_id_idx ON echoes(author_user_id);
CREATE INDEX echoes_place_id_status_idx ON echoes(place_id, status);
CREATE INDEX echoes_published_at_idx ON echoes(published_at DESC) WHERE published_at IS NOT NULL;
CREATE INDEX echoes_public_location_gist_idx ON echoes USING gist(public_location);

CREATE TABLE echo_links (
    id uuid PRIMARY KEY,
    source_echo_id uuid NOT NULL REFERENCES echoes(id) ON DELETE CASCADE,
    target_echo_id uuid NOT NULL REFERENCES echoes(id) ON DELETE CASCADE,
    link_type text NOT NULL CHECK (link_type IN ('stitch')),
    quoted_reply_id uuid,
    quote_snapshot_media_asset_id uuid,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (source_echo_id, target_echo_id, link_type),
    CHECK (source_echo_id <> target_echo_id)
);

CREATE INDEX echo_links_target_echo_id_idx ON echo_links(target_echo_id);

CREATE TABLE replies (
    id uuid PRIMARY KEY,
    echo_id uuid NOT NULL REFERENCES echoes(id) ON DELETE CASCADE,
    author_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    parent_reply_id uuid REFERENCES replies(id) ON DELETE CASCADE,
    body_text text NOT NULL,
    status text NOT NULL DEFAULT 'published' CHECK (status IN ('published', 'limited', 'removed', 'deleted')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    edited_at timestamptz,
    deleted_at timestamptz,
    CHECK (char_length(body_text) BETWEEN 1 AND 500)
);

CREATE INDEX replies_echo_id_created_at_idx ON replies(echo_id, created_at);
CREATE INDEX replies_author_user_id_idx ON replies(author_user_id);

CREATE TABLE media_assets (
    id uuid PRIMARY KEY,
    owner_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    echo_id uuid REFERENCES echoes(id) ON DELETE CASCADE,
    reply_id uuid REFERENCES replies(id) ON DELETE CASCADE,
    media_type text NOT NULL CHECK (media_type IN ('image', 'audio', 'video', 'quote_snapshot')),
    storage_bucket text NOT NULL,
    object_key text NOT NULL,
    content_type text NOT NULL,
    byte_size bigint CHECK (byte_size IS NULL OR byte_size >= 0),
    duration_ms integer CHECK (duration_ms IS NULL OR duration_ms >= 0),
    width integer CHECK (width IS NULL OR width > 0),
    height integer CHECK (height IS NULL OR height > 0),
    status text NOT NULL DEFAULT 'pending_upload' CHECK (status IN ('pending_upload', 'uploaded', 'processing', 'approved', 'rejected', 'failed', 'deleted')),
    sha256_hash bytea,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    UNIQUE (storage_bucket, object_key)
);

CREATE INDEX media_assets_echo_id_idx ON media_assets(echo_id);
CREATE INDEX media_assets_owner_user_id_idx ON media_assets(owner_user_id);

ALTER TABLE user_profiles
    ADD CONSTRAINT user_profiles_avatar_media_asset_id_fkey
    FOREIGN KEY (avatar_media_asset_id) REFERENCES media_assets(id) ON DELETE SET NULL;

ALTER TABLE echo_links
    ADD CONSTRAINT echo_links_quoted_reply_id_fkey
    FOREIGN KEY (quoted_reply_id) REFERENCES replies(id) ON DELETE SET NULL,
    ADD CONSTRAINT echo_links_quote_snapshot_media_asset_id_fkey
    FOREIGN KEY (quote_snapshot_media_asset_id) REFERENCES media_assets(id) ON DELETE SET NULL;

CREATE TABLE media_derivatives (
    id uuid PRIMARY KEY,
    media_asset_id uuid NOT NULL REFERENCES media_assets(id) ON DELETE CASCADE,
    derivative_type text NOT NULL CHECK (derivative_type IN ('thumbnail', 'preview', 'transcode', 'waveform', 'transcript')),
    storage_bucket text NOT NULL,
    object_key text NOT NULL,
    content_type text NOT NULL,
    byte_size bigint CHECK (byte_size IS NULL OR byte_size >= 0),
    width integer CHECK (width IS NULL OR width > 0),
    height integer CHECK (height IS NULL OR height > 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (storage_bucket, object_key)
);

CREATE INDEX media_derivatives_media_asset_id_idx ON media_derivatives(media_asset_id);

CREATE TABLE reactions (
    echo_id uuid NOT NULL REFERENCES echoes(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    reaction_type text NOT NULL CHECK (reaction_type IN ('heart', 'fire', 'sad', 'laugh', 'clap', 'mind_blown')),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (echo_id, user_id)
);

CREATE INDEX reactions_user_id_idx ON reactions(user_id);

CREATE TABLE bookmarks (
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    echo_id uuid REFERENCES echoes(id) ON DELETE CASCADE,
    place_id uuid REFERENCES places(id) ON DELETE CASCADE,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK ((echo_id IS NOT NULL)::integer + (place_id IS NOT NULL)::integer = 1),
    UNIQUE (user_id, echo_id),
    UNIQUE (user_id, place_id)
);

CREATE TABLE reports (
    id uuid PRIMARY KEY,
    reporter_user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    echo_id uuid REFERENCES echoes(id) ON DELETE CASCADE,
    reply_id uuid REFERENCES replies(id) ON DELETE CASCADE,
    place_id uuid REFERENCES places(id) ON DELETE CASCADE,
    reported_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    category text NOT NULL CHECK (category IN ('harassment', 'hate', 'sexual_content', 'violence_threat', 'illegal_dangerous', 'privacy_location_safety', 'spam_scam', 'misinformation', 'sensitive_place', 'intellectual_property', 'other')),
    details text,
    status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'reviewing', 'actioned', 'dismissed')),
    created_at timestamptz NOT NULL DEFAULT now(),
    resolved_at timestamptz,
    CHECK ((echo_id IS NOT NULL)::integer + (reply_id IS NOT NULL)::integer + (place_id IS NOT NULL)::integer + (reported_user_id IS NOT NULL)::integer >= 1)
);

CREATE INDEX reports_status_created_at_idx ON reports(status, created_at);
CREATE INDEX reports_reporter_user_id_idx ON reports(reporter_user_id);

CREATE TABLE moderation_actions (
    id uuid PRIMARY KEY,
    moderator_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    report_id uuid REFERENCES reports(id) ON DELETE SET NULL,
    target_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    echo_id uuid REFERENCES echoes(id) ON DELETE SET NULL,
    reply_id uuid REFERENCES replies(id) ON DELETE SET NULL,
    place_id uuid REFERENCES places(id) ON DELETE SET NULL,
    action_type text NOT NULL CHECK (action_type IN ('limit', 'remove', 'restore', 'warn', 'restrict_posting', 'suspend', 'ban', 'sensitive_label', 'place_restrict', 'place_merge')),
    reason_code text NOT NULL,
    notes text,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX moderation_actions_created_at_idx ON moderation_actions(created_at DESC);
CREATE INDEX moderation_actions_target_user_id_idx ON moderation_actions(target_user_id);

CREATE TABLE appeals (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    moderation_action_id uuid NOT NULL REFERENCES moderation_actions(id) ON DELETE CASCADE,
    body_text text NOT NULL,
    status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'accepted', 'rejected', 'withdrawn')),
    created_at timestamptz NOT NULL DEFAULT now(),
    resolved_at timestamptz,
    resolved_by_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    CHECK (char_length(body_text) BETWEEN 1 AND 2000)
);

CREATE INDEX appeals_status_created_at_idx ON appeals(status, created_at);

CREATE TABLE blocks (
    blocker_user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    blocked_user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (blocker_user_id, blocked_user_id),
    CHECK (blocker_user_id <> blocked_user_id)
);

CREATE INDEX blocks_blocked_user_id_idx ON blocks(blocked_user_id);

CREATE TABLE notifications (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    type text NOT NULL,
    actor_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    echo_id uuid REFERENCES echoes(id) ON DELETE CASCADE,
    reply_id uuid REFERENCES replies(id) ON DELETE CASCADE,
    place_id uuid REFERENCES places(id) ON DELETE CASCADE,
    payload jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    read_at timestamptz,
    expires_at timestamptz
);

CREATE INDEX notifications_user_id_created_at_idx ON notifications(user_id, created_at DESC);

CREATE TABLE analytics_events (
    id uuid PRIMARY KEY,
    user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    session_id uuid REFERENCES sessions(id) ON DELETE SET NULL,
    event_name text NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    properties jsonb NOT NULL DEFAULT '{}'::jsonb,
    ip_hash bytea,
    user_agent text
);

CREATE INDEX analytics_events_occurred_at_idx ON analytics_events(occurred_at);
CREATE INDEX analytics_events_event_name_idx ON analytics_events(event_name);

CREATE TABLE audit_logs (
    id uuid PRIMARY KEY,
    actor_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    actor_kind text NOT NULL DEFAULT 'user' CHECK (actor_kind IN ('user', 'service', 'system')),
    action text NOT NULL,
    target_table text,
    target_id uuid,
    reason text,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX audit_logs_created_at_idx ON audit_logs(created_at DESC);
CREATE INDEX audit_logs_target_idx ON audit_logs(target_table, target_id);

CREATE TABLE jobs (
    id uuid PRIMARY KEY,
    queue text NOT NULL,
    job_type text NOT NULL,
    status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'dead', 'cancelled')),
    payload jsonb NOT NULL DEFAULT '{}'::jsonb,
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    max_attempts integer NOT NULL DEFAULT 3 CHECK (max_attempts > 0),
    run_after timestamptz NOT NULL DEFAULT now(),
    locked_by text,
    locked_at timestamptz,
    last_error text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz
);

CREATE INDEX jobs_queue_status_run_after_idx ON jobs(queue, status, run_after);
CREATE INDEX jobs_locked_at_idx ON jobs(locked_at) WHERE locked_at IS NOT NULL;

CREATE TABLE idempotency_keys (
    id uuid PRIMARY KEY,
    user_id uuid REFERENCES users(id) ON DELETE CASCADE,
    key text NOT NULL,
    request_hash bytea NOT NULL,
    response_status integer,
    response_body jsonb,
    locked_until timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    UNIQUE (user_id, key)
);

CREATE INDEX idempotency_keys_expires_at_idx ON idempotency_keys(expires_at);

CREATE TABLE invite_codes (
    id uuid PRIMARY KEY,
    code_hash bytea NOT NULL UNIQUE,
    created_by_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    claimed_by_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
    max_uses integer NOT NULL DEFAULT 1 CHECK (max_uses > 0),
    uses_count integer NOT NULL DEFAULT 0 CHECK (uses_count >= 0),
    expires_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    claimed_at timestamptz,
    CHECK (uses_count <= max_uses)
);

CREATE INDEX invite_codes_expires_at_idx ON invite_codes(expires_at);
